import{_ as d,C as c,o as s,c as i,aj as o,E as n,j as t,a as r}from"./framework.js";const b=JSON.parse('{"title":"Currencies | Commerce | Admin CMS","description":"Configure the site default currency and additional currencies with exchange rates relative to the default, for multi-currency display and conversion. Carts / orders can switch trial…","frontmatter":{"title":"Currencies | Commerce | Admin CMS","description":"Configure the site default currency and additional currencies with exchange rates relative to the default, for multi-currency display and conversion. Carts / orders can switch trial…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/commerce/currencies.html"}]]},"headers":[],"relativePath":"cms/commerce/currencies.md","filePath":"en/cms/commerce/currencies.md","lastUpdated":1781010536000}'),l={name:"cms/commerce/currencies.md"};function u(h,e,m,g,p,f){const a=c("DocImage");return s(),i("div",null,[e[0]||(e[0]=o('<h1 id="currencies" tabindex="-1">Currencies <a class="header-anchor" href="#currencies" aria-label="Permalink to &quot;Currencies&quot;">​</a></h1><blockquote><p>Menu: <strong>Commerce -&gt; Currencies</strong><br> Deep link: <code>/_Admin/commerce/currencies?SiteId={siteGuid}</code></p></blockquote><p>Configure the site <strong>default currency</strong> and <strong>additional currencies</strong> with <strong>exchange rates</strong> relative to the default, for multi-currency display and conversion. <a href="./carts.html">Carts</a> / <a href="./orders.html">orders</a> can switch trial currency when multiple currencies are enabled; product and shipping amounts are based on the default currency, with other currencies converted by rate. Data is stored in Commerce <code>settings</code> (<code>currencyCode</code>, <code>currencySymbol</code>, <code>currencies[]</code>), alongside other global items in <a href="./settings.html">settings</a>; <strong>default currency is maintained on this page</strong>.</p><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In the <a href="./../navigation.html#edit-menu">Edit menu</a>, enable <strong>Commerce -&gt; Currencies</strong> (and the parent <strong>Commerce</strong> group).</li><li>Open <strong>Commerce -&gt; Currencies</strong> in the left sidebar.</li></ol><h2 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h2><p>Path: <code>/_Admin/commerce/currencies?SiteId=...</code></p><h3 id="default-currency" tabindex="-1">Default Currency <a class="header-anchor" href="#default-currency" aria-label="Permalink to &quot;Default Currency&quot;">​</a></h3><p>Top-right <strong>Default currency</strong> dropdown: select <code>currencyCode</code> from the system currency library (options like <code>USD - US Dollar - $</code>). When switching with additional currencies configured, a <strong>confirmation</strong> appears; on confirm, <strong>all additional currencies are cleared</strong>, default symbol updates, then <code>settings</code> is saved.</p><div class="warning custom-block"><p class="custom-block-title">Switching default currency</p><p>Changing the default currency removes <strong>all</strong> currently configured <strong>additional currencies</strong>; you must re-add them and set exchange rates. Confirm impact on historical order display and storefront multi-currency before proceeding.</p></div><h3 id="table-and-actions" tabindex="-1">Table and Actions <a class="header-anchor" href="#table-and-actions" aria-label="Permalink to &quot;Table and Actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column / Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>ISO-style currency code, e.g. <code>USD</code>, <code>CNY</code></td></tr><tr><td><strong>Symbol</strong></td><td>Display symbol</td></tr><tr><td><strong>Name</strong></td><td>Localized name (<code>nameNative</code>)</td></tr><tr><td><strong>Exchange rate</strong></td><td><code>exchangeRate</code> relative to <strong>default currency</strong>; list shows 6 decimal places</td></tr><tr><td><strong>Auto update</strong></td><td>Whether to pull latest rate from server (<code>autoUpdate</code>)</td></tr><tr><td><strong>Add currency</strong></td><td>Dropdown: currencies not yet added and not the default; on select, fetches <code>getRate(default, target)</code> as initial rate and opens <a href="#add-edit-currency-dialog">edit dialog</a></td></tr><tr><td><strong>Edit</strong></td><td>Row pencil; change rate and auto update</td></tr><tr><td><strong>Batch delete</strong></td><td>Select additional currency rows → <strong>Delete</strong> → remove from <code>settings.currencies</code> and save (default currency row cannot be deleted)</td></tr></tbody></table>',12)),n(a,{src:"/cms/commerce/currencies-list.png",alt:"Currency list: add currency, default dropdown and rate table",width:"1120"}),e[1]||(e[1]=t("h3",{id:"add-edit-currency-dialog",tabindex:"-1"},[r("Add / Edit Currency Dialog "),t("a",{class:"header-anchor",href:"#add-edit-currency-dialog","aria-label":'Permalink to "Add / Edit Currency Dialog"'},"​")],-1)),e[2]||(e[2]=t("p",null,[r("Opened from "),t("strong",null,"Add currency"),r(" or row "),t("strong",null,"Edit"),r(" (in-page dialog, no separate route).")],-1)),n(a,{src:"/cms/commerce/currencies-edit-dialog.png",alt:"Edit currency dialog: code, rate and auto update",width:"720"}),e[3]||(e[3]=o('<table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>Read-only; matches selected currency</td></tr><tr><td><strong>Exchange rate</strong></td><td>Number, 6 decimal places, minimum <code>0.000001</code>; disabled when <strong>Auto update</strong> is on</td></tr><tr><td><strong>Auto update</strong></td><td>When enabled, system periodically updates rate from default currency (saved to <code>settings.currencies</code>)</td></tr></tbody></table><p>Confirm <strong>Save</strong> writes site settings and refreshes the list; <strong>Cancel</strong> closes the dialog.</p><h2 id="relationship-with-other-modules" tabindex="-1">Relationship with Other Modules <a class="header-anchor" href="#relationship-with-other-modules" aria-label="Permalink to &quot;Relationship with Other Modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Description</th></tr></thead><tbody><tr><td><a href="./carts.html">Carts</a> / <a href="./orders.html">Orders</a></td><td>When additional currencies exist, create/edit/checkout pages may show currency switcher; trial uses corresponding <code>exchangeRate</code></td></tr><tr><td><a href="./shippings.html">Shipping</a></td><td>Base shipping fee suffix uses current default <code>currencyCode</code></td></tr><tr><td><a href="./settings.html">Settings</a></td><td>Weight unit, payment methods, custom fields, etc.; default currency is maintained on this page</td></tr></tbody></table><p>Script API: <a href="/kb-docs/api/commerce/currency.html">k.commerce.currency</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./settings.html">Settings</a></li><li><a href="./orders.html">Orders</a></li><li><a href="/kb-docs/api/commerce/currency.html">k.commerce.currency</a></li></ul>',7))])}const C=d(l,[["render",u]]);export{b as __pageData,C as default};
